 "sql4-private": {
  "db": "w4_private",
  "note": "Бұл сайттың өз жаттығуы, ресми тапсырма емес: деректер ойдан шығарылған, дерекқор кішірейтілген. Кітап шифры: cipher кестесінде үштіктер дайын (sentence_id - сөйлем нөмірі, start - бастапқы таңба, length - ұзындық), мәтін sentences кестесінде. Көріністі жасаудың орнына, оның ішіндегі SELECT сұрауын жазыңыз (не CREATE VIEW ...; SELECT * FROM ...; деп жазсаңыз да болады: тексеруші соңғы нәтижені алады). ",
  "tasks": [
   {
    "f": "first_phrase",
    "t": "cipher кестесіндегі 1-үштікті (id = 1) шешіңіз: бір фраза.",
    "ref": "SELECT substr(\"sentence\", \"start\", \"length\") FROM \"cipher\" JOIN \"sentences\" ON \"sentences\".\"id\" = \"cipher\".\"sentence_id\" WHERE \"cipher\".\"id\" = 1;"
   },
   {
    "f": "message",
    "t": "Бүкіл хабар: phrase бағанында әр фраза бір жолда, cipher.id реті бойынша.",
    "ref": "SELECT substr(\"sentence\", \"start\", \"length\") AS \"phrase\" FROM \"cipher\" JOIN \"sentences\" ON \"sentences\".\"id\" = \"cipher\".\"sentence_id\" ORDER BY \"cipher\".\"id\";"
   },
   {
    "f": "one_line",
    "t": "Фразаларды бір жолға бос орынмен біріктіріңіз (group_concat), тәртібі cipher.id бойынша: бір баған, бір жол.",
    "ref": "SELECT group_concat(\"phrase\", ' ') FROM (SELECT substr(\"sentence\", \"start\", \"length\") AS \"phrase\" FROM \"cipher\" JOIN \"sentences\" ON \"sentences\".\"id\" = \"cipher\".\"sentence_id\" ORDER BY \"cipher\".\"id\");"
   },
   {
    "f": "longest_phrase",
    "t": "Ең ұзын фразаны (length ең үлкен) табыңыз: бір баған, бір жол.",
    "ref": "SELECT substr(\"sentence\", \"start\", \"length\") FROM \"cipher\" JOIN \"sentences\" ON \"sentences\".\"id\" = \"cipher\".\"sentence_id\" ORDER BY \"length\" DESC LIMIT 1;"
   },
   {
    "f": "used_sentences",
    "t": "Шифрда қолданылған сөйлемдердің толық мәтіні (sentence бағаны), қайталанбай.",
    "ref": "SELECT \"sentence\" FROM \"sentences\" WHERE \"id\" IN (SELECT \"sentence_id\" FROM \"cipher\");"
   }
  ]
 }
